"""Build a self-contained SVG review using exact original-frame file copies."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
DATA=json.loads((ROOT/"profile-fit-candidate.json").read_text(encoding="utf-8"))
TEMPLATE=r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Rainee · provisional paired lobe profiles</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#12151b;color:#e7ecf6;font:15px system-ui,sans-serif}header{padding:22px 28px;border-bottom:1px solid #334053}h1{margin:0 0 8px;font-size:23px}.note{color:#b8c5d9;line-height:1.5;margin:8px 0;max-width:1050px}.badge{display:inline-block;background:#564019;padding:4px 8px;border-radius:5px;color:#ffe7a5}main{display:grid;grid-template-columns:minmax(420px,1fr) 390px;gap:20px;padding:20px 28px}.image-wrap{position:relative;max-width:1024px;border:1px solid #475168;background:black;touch-action:none}svg{width:100%;height:auto;display:block}aside{background:#1b212c;padding:17px;border:1px solid #354154;border-radius:8px}label{display:block;margin:12px 0 5px}button,select,input{font:inherit;background:#242e3d;color:#fff;border:1px solid #556780;border-radius:5px;padding:7px}button{cursor:pointer}button:hover{background:#33475f}input[type=number]{width:100%}.row{display:grid;grid-template-columns:1fr 1fr;gap:9px}.small{font-size:12px;color:#aebed4;line-height:1.5}.stats{margin:15px 0;border-collapse:collapse;width:100%}.stats td{border-bottom:1px solid #344156;padding:6px 0}.stats td:last-child{text-align:right;font-variant-numeric:tabular-nums}.handle{cursor:move;stroke:#fff;stroke-width:2}.legend{padding:10px 0;display:flex;gap:14px;flex-wrap:wrap;font-size:12px}.dot{display:inline-block;width:10px;height:10px;margin-right:5px}details{margin-top:14px}summary{cursor:pointer}textarea{width:100%;height:240px;color:#dae7f5;background:#111722;border:1px solid #4c5c72;resize:vertical;font:11px monospace}#roi{width:100%;height:auto;border:1px solid #475168}.warning{color:#ffd798}a{color:#96c7ff}@media(max-width:900px){main{grid-template-columns:1fr;padding:15px}header{padding:18px}aside{max-width:none}}
/* Keep the entire source frame alongside controls on a 720 px display. */
header{padding:12px 20px}h1{display:inline-block;font-size:20px;margin:0 12px 5px 0}.badge{font-size:12px;padding:3px 7px}.note{font-size:12px;line-height:1.4;margin:4px 0;max-width:none}main{grid-template-columns:minmax(340px,1fr) 350px;gap:14px;padding:12px 20px}.image-wrap{max-width:none}svg#view{height:clamp(340px,calc(100dvh - 170px),1000px);width:100%}aside{padding:12px;max-height:calc(100dvh - 125px);overflow:auto;font-size:13px}aside label{margin:7px 0 3px}aside button,aside select,aside input{padding:5px;font-size:13px}.stats{margin:9px 0}.stats td{padding:4px 0}.legend{padding:6px 0;gap:9px;font-size:11px}.small{font-size:11px;line-height:1.4}details{margin-top:9px}@media(max-width:850px){main{grid-template-columns:1fr;padding:10px}header{padding:12px}aside{max-height:none;overflow:visible}svg#view{height:clamp(340px,calc(100dvh - 170px),800px)}}
</style>
<header><h1>Rainee · paired lobe profile review</h1><span class="badge">Provisional editable measurements</span><p class="note">Full frames stay unchanged and uncropped. Curves follow reviewed visible edges; dashed ellipses describe exposed-region area and shape, including clothing occlusion. They are not anatomical centers or 3D tissue volume.</p><p class="note">Accepted ordinal stages: 0000 baseline → 0010 → 0018 → 0026 endpoint. Frame0049 is excluded. Source stature is a separate constraint.</p></header>
<main><section><div class="image-wrap"><svg id="view" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024" width="1024" height="1024" preserveAspectRatio="xMidYMid meet" aria-label="Full-frame profile overlay"><image id="source" width="1024" height="1024" preserveAspectRatio="xMidYMid meet"/><g id="overlay"></g></svg></div><div class="legend"><span><i class="dot" style="background:#5aebed"></i>Image-left outside curve</span><span><i class="dot" style="background:#ffe76a"></i>Image-right outside curve</span><span><i class="dot" style="background:#95ff93"></i>Area-equivalent left ellipse</span><span><i class="dot" style="background:#fd93e6"></i>Area-equivalent right ellipse</span><span><i class="dot" style="background:#ffae70"></i>Visible back-skin span</span></div><p class="small">Drag a center or torso endpoint; edit axes/rotation at right. Export saves proposals separately from measured source descriptors. Re-extract curves with editable guide-annotations.json.</p></section>
<aside><label for="frame">Accepted reference stage</label><select id="frame"></select><label><input id="visible" type="checkbox" checked> Show measurement overlay</label><label><input id="arcfits" type="checkbox"> Show free outside-arc ellipse diagnostics</label><label><input id="polygons" type="checkbox"> Show exposed-region area polygons</label><table class="stats" id="stats"></table><div class="warning small" id="warnings"></div><label for="lobe">Editable descriptive ellipse</label><select id="lobe"><option value="left">Image-left region</option><option value="right">Image-right region</option></select><div class="row"><div><label>Center X px</label><input id="cx" type="number" step="0.1"></div><div><label>Center Y px</label><input id="cy" type="number" step="0.1"></div><div><label>Semimajor px</label><input id="a" type="number" min="1" step="0.1"></div><div><label>Semiminor px</label><input id="b" type="number" min="1" step="0.1"></div></div><label>Major-axis rotation degrees</label><input id="angle" type="number" step="0.1"><div class="row"><button id="reset">Reset this stage</button><button id="export">Export JSON</button></div><details><summary>Generated 3D ROI context</summary><p class="small">These are provisional source-axis/skin-color selections on independently generated meshes. They are not registered to the image camera, and they do not establish corresponding anatomical regions. A smaller stage0026 descriptor cannot override the accepted endpoint.</p><img id="roi" alt="Three-view source ROI inspection"><p class="small" id="roiStats"></p></details><details><summary>Method and uncertainty</summary><p class="small">Review-guided outer arcs are sampled every ~3 px. A blurred-Lab derivative searches ±8 px along curve normals. Soft-L1 rotated ellipse/circle fits use outside arcs only. Partial-arc fits can have low curve error yet highly unstable hidden centers/radii; those are diagnostics. The primary ellipse uses exact polygon area/centroid/second moments and preserves the visible polygon area.</p><p class="small">The denominator is a manually annotated visible exposed lower-back skin span at image row620, excluding sleeves. It is garment/pose dependent. ±8 px endpoint tolerance is shown in JSON, not a claim of anatomical measurement accuracy. Shape sensitivity uses correlated ±3 px outside-curve jitter and ±5 px clothing/cleft closure jitter; it excludes pose and generation uncertainty.</p><p class="small">For camera fitting, use the observed outside curves and supports first. Downweight the occluded seams and clipped lower poles. Do not turn ellipse/pixel area or stage labels into physical volume multipliers.</p></details><details><summary>Current candidate JSON</summary><textarea id="json" readonly></textarea><p class="small"><a href="profile-fit-candidate.json" download>Measured candidate</a> · <a href="guide-annotations.json" download>Editable contour guides</a></p></details></aside></main>
<script id="data" type="application/json">__DATA__</script>
<script>
const original=JSON.parse(document.getElementById('data').textContent),data=structuredClone(original),edits={};
const $=id=>document.getElementById(id),ns='http://www.w3.org/2000/svg';
let active=0,drag=null;
function frame(){return data.frames[active]}
function make(tag,attrs,parent=$('overlay')){let n=document.createElementNS(ns,tag);for(let [k,v]of Object.entries(attrs))n.setAttribute(k,v);parent.append(n);return n}
function geom(e){let t=e.major_rotation_degrees*Math.PI/180,a=e.semimajor_px,b=e.semiminor_px,c=Math.cos(t),s=Math.sin(t),xx=a*a*c*c+b*b*s*s,yy=a*a*s*s+b*b*c*c,xy=(a*a-b*b)*c*s,[x,y]=e.center_px,sx=Math.sqrt(xx),sy=Math.sqrt(yy);return{upper_pole_px:[x-xy/sy,y-sy],lower_pole_px:[x+xy/sy,y+sy],left_pole_px:[x-sx,y-xy/sx],right_pole_px:[x+sx,y+xy/sx],projected_width_px:2*sx,projected_height_px:2*sy,ellipse_area_px2:Math.PI*a*b}}
function ellipse(e,color,dash,width){let [x,y]=e.center_px;make('ellipse',{cx:x,cy:y,rx:e.semimajor_px,ry:e.semiminor_px,transform:`rotate(${e.major_rotation_degrees} ${x} ${y})`,fill:'none',stroke:color,'stroke-width':width,'stroke-dasharray':dash})}
function mark(pt,color,type,size=6){let n=make('circle',{cx:pt[0],cy:pt[1],r:size,fill:color,class:'handle','data-kind':type});return n}
function toPoints(p){return p.map(v=>v.join(',')).join(' ')}
function noteEdit(kind){edits[frame().frame_number]={status:'manual_overlay_proposal_not_refitted',edited_at:new Date().toISOString(),ellipse_proposals:Object.fromEntries(['left','right'].map(s=>[s,structuredClone(frame().lobes[s].ellipse)])),torso_endpoints_px:structuredClone(frame().torso_span.endpoints_px),last_edit:kind}}
function render(){let f=frame();$('source').setAttribute('href',f.image.review_path);$('overlay').innerHTML='';if($('visible').checked){for(let s of ['left','right']){let l=f.lobes[s],color=s==='left'?'#5aebed':'#ffe76a',ec=s==='left'?'#95ff93':'#fd93e6';if($('polygons').checked)make('polygon',{points:toPoints(l.visible_region_polygon_px),fill:color,'fill-opacity':'.12',stroke:color,'stroke-width':1});make('polyline',{points:toPoints(l.selected_outside_curve_px),fill:'none',stroke:color,'stroke-width':3});ellipse(l.ellipse,ec,'8 7',2.2);if($('arcfits').checked)ellipse(l.outside_curve_ellipse_fit.ellipse,'#fff','3 6',1.5);mark(l.ellipse.center_px,ec,s);let g=geom(l.ellipse);for(let name of ['upper_pole_px','lower_pole_px'])make('path',{d:`M ${g[name][0]-6} ${g[name][1]} h12 M ${g[name][0]} ${g[name][1]-6} v12`,stroke:ec,'stroke-width':2});}let [p,q]=f.torso_span.endpoints_px;make('line',{x1:p[0],y1:p[1],x2:q[0],y2:q[1],stroke:'#ffae70','stroke-width':3});mark(p,'#ffae70','torso0');mark(q,'#ffae70','torso1');make('text',{x:(p[0]+q[0])/2,y:p[1]-12,fill:'#ffd8b8','font-size':15,'text-anchor':'middle','paint-order':'stroke',stroke:'#111','stroke-width':3}).textContent='visible back skin span';}
let p=f.paired_profile,tw=Math.abs(f.torso_span.endpoints_px[1][0]-f.torso_span.endpoints_px[0][0]);let rows=[['Measured outside width',p.visible_outside_width_px.toFixed(1)+' px'],['Measured visible skin area',Math.round(p.sum_visible_skin_region_area_px2).toLocaleString()+' px²'],['Measured width / baseline',p.apparent_width_ratio_to_baseline.toFixed(3)],['Current back-skin span',tw.toFixed(1)+' px'],['Outside width / current span',(p.visible_outside_width_px/tw).toFixed(3)],['Overlay status',edits[f.frame_number]?'Edited proposal':'Measured candidate']];$('stats').innerHTML=rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('');
let warnings=[];for(let s of ['left','right']){let l=f.lobes[s];if(l.outside_curve_ellipse_fit.identifiability.startsWith('ill_'))warnings.push(`${s}: hidden center/radii from free arc fit are ill-conditioned.`);if(l.lower_pole_status.includes('truncated'))warnings.push(`${s}: lower region meets the image boundary; true lower extent is unknown.`)}$('warnings').textContent=warnings.join(' ');$('roi').src=`../frame_${String(f.frame_number).padStart(4,'0')}/local-roi-preview.png`;let r=f.generated_3d_context;$('roiStats').textContent=`Unregistered 3D rear/waist width ${r.rear_to_waist_width.toFixed(3)}; rear depth/width ${r.rear_depth_over_width.toFixed(3)}. Axes, ROI and pose are unaccepted.`;$('json').value=JSON.stringify({schema:data.schema,status:data.status,frame:f,manual_overlay_proposal:edits[f.frame_number]||null},null,2);}
function populate(){let e=frame().lobes[$('lobe').value].ellipse;for(let [id,v] of [['cx',e.center_px[0]],['cy',e.center_px[1]],['a',e.semimajor_px],['b',e.semiminor_px],['angle',e.major_rotation_degrees]])$(id).value=v.toFixed(2)}
for(let f of data.frames){let o=document.createElement('option');o.value=data.frames.indexOf(f);o.textContent=`Stage ${f.stage_ordinal} · frame${String(f.frame_number).padStart(4,'0')}${f.frame_number===0?' baseline':f.frame_number===26?' endpoint':''}`;$('frame').append(o)}
$('frame').onchange=()=>{active=Number($('frame').value);render();populate()};$('lobe').onchange=populate;for(let id of ['visible','arcfits','polygons'])$(id).onchange=render;
function editEllipse(){let e=frame().lobes[$('lobe').value].ellipse,vals=['cx','cy','a','b','angle'].map(k=>Number($(k).value));if(!vals.every(Number.isFinite)||vals[2]<=0||vals[3]<=0)return;e.center_px=vals.slice(0,2);e.semimajor_px=vals[2];e.semiminor_px=vals[3];e.major_rotation_degrees=vals[4];frame().lobes[$('lobe').value].ellipse_derived=geom(e);noteEdit('ellipse_numeric');render()}
for(let id of ['cx','cy','a','b','angle']){$(id).oninput=editEllipse;$(id).onchange=editEllipse}
$('reset').onclick=()=>{data.frames[active]=structuredClone(original.frames[active]);delete edits[frame().frame_number];render();populate()};
$('export').onclick=()=>{let exportData=structuredClone(original);exportData.manual_overlay_proposals=edits;exportData.manual_overlay_proposals_are_not_refitted=true;let b=new Blob([JSON.stringify(exportData,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='rainee-profile-review-proposals.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
function pointer(ev){let p=$('view').createSVGPoint();p.x=ev.clientX;p.y=ev.clientY;return p.matrixTransform($('view').getScreenCTM().inverse())}
$('view').onpointerdown=ev=>{let kind=ev.target.getAttribute('data-kind');if(!kind)return;drag=kind;$('view').setPointerCapture(ev.pointerId);ev.preventDefault()};
$('view').onpointermove=ev=>{if(!drag)return;let p=pointer(ev),pt=[Math.max(0,Math.min(1024,p.x)),Math.max(0,Math.min(1024,p.y))];if(drag.startsWith('torso')){let n=Number(drag.slice(5)),other=frame().torso_span.endpoints_px[1-n];pt[1]=other[1];frame().torso_span.endpoints_px[n]=pt}else{frame().lobes[drag].ellipse.center_px=pt;frame().lobes[drag].ellipse_derived=geom(frame().lobes[drag].ellipse)}noteEdit(drag);render();populate()};
$('view').onpointerup=()=>drag=null;$('view').onpointercancel=()=>drag=null;render();populate();
</script></html>'''
(ROOT/"review.html").write_text(TEMPLATE.replace('__DATA__',json.dumps(DATA,separators=(',',':')).replace('</','<\\/')),encoding='utf-8')
print(ROOT/'review.html')
